// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        address(c).call{value: 1 ether}("");
        vm.deal(address(this), 100 ether);
        c.sendMoney(address(1), 0.5 ether);
        bool success;
        try c.withdraw(1 ether) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == false);
    }
}
